    static ServerMatch game(String id,Set<PokemonFamily> families,AttackDefinition attack){
        var kinds=List.of("basic","basic","evolved","trainer","badge","energy",PLASMA,"stadium");var defs=new ArrayList<CardDefinition>();var pokemon=new HashMap<String,PokemonProfile>();var trainers=Map.of("trainer",profile(id),"badge",profile(BADGE),"stadium",profile("sm6_en_111"));
        for(String key:new LinkedHashSet<>(kinds)){boolean mon=Set.of("basic","evolved").contains(key),en=Set.of("energy",PLASMA).contains(key);defs.add(new CardDefinition(key,key,mon?CardCategory.POKEMON:en?CardCategory.ENERGY:CardCategory.TRAINER,mon||en?TrainerCategory.NONE:trainers.get(key).category(),"H",Set.of("international"),key.equals("basic"),key.equals("energy"),60,Map.of(),EffectSupport.SUPPORTED,null,mon?families:Set.of(),mon?Set.of(EnergyType.WATER):Set.of()));if(mon)pokemon.put(key,new PokemonProfile(1000,1,key.equals("evolved")?"basic":null,null,0,null,0,1,List.of(attack),List.of(NonPokemonBatch74Test.passive("{\"type\":\"tool_capacity\",\"target\":\"SELF\",\"amount\":2}")),EnergyType.WATER));}
        var catalog=new CombatCatalog(pokemon,Map.of("energy",EnergyType.GRASS),trainers,Map.of(PLASMA,NonPokemonBatch2Test.DATA.energyProfile(PLASMA).orElseThrow()));
        for(int seed=0;seed<1000;seed++){var decks=new ArrayList<List<CardInstance>>();for(UUID p:List.of(A,B)){var cards=new ArrayList<CardInstance>();for(int i=0;i<60;i++)cards.add(new CardInstance(new UUID(p.getLeastSignificantBits(),i+1),p,kinds.get(i%kinds.size())));decks.add(cards);}var m=new ServerMatch(A,B,decks.get(0),decks.get(1),GeneratedRuleBatch8Test.RULES,new CardDatabase(defs),catalog,new ServerRandom(seed));OpeningTestSupport.decideOrder(m,A,B);if(List.of(A,B).stream().anyMatch(p->m.privateView(p).hand().stream().filter(c->c.definitionId().equals("basic")).count()<2))continue;OpeningTestSupport.complete(m,A,B,1);m.drawCardsByEffect(A,A,24);m.drawCardsByEffect(A,B,24);m.endTurn(A);m.endTurn(B);if(List.of(A,B).stream().allMatch(p->new HashSet<>(kinds).stream().allMatch(k->m.privateView(p).hand().stream().anyMatch(c->c.definitionId().equals(k)))&&m.privateView(p).deck().stream().anyMatch(c->c.definitionId().equals(PLASMA))))return m;}throw new AssertionError("Plasma live-field fixture unavailable");
    }
    static ServerMatch game(String id){return game(id,Set.of(),GeneratedRuleBatch8Test.hit(100,false));}
    static CardInstance attach(ServerMatch m,UUID p,UUID host,String alias){var c=hand(m,p,alias);m.attachToolByEffect(m.currentPlayer(),p,EffectSourceZone.HAND,c.instanceId(),p,host);return c;}
    static ServerMatch aiGame(String id){var m=game(id,Set.of(),GeneratedRuleBatch8Test.hit(300,false));if(id.equals(MACHINE)||id.equals(TRIGGER))for(UUID p:List.of(A,B))attach(m,p,active(m,p),"badge");return m;}
    public static void main(String[] args){badge();machine();mirror();trigger();ai();schema();System.out.println("NonPokemonBatch112Test passed: live/printed Team Plasma membership, both owners/positions/evolution/removal/suppression, Machine exact deck Energy and own eligible recipients, Silver Mirror opponent Plasma damage/effects and legacy EX exclusion, Reversal Trigger damage-only KO and post-attack affiliation, private any-card search, unchanged Prizes, four AI difficulties");}
    static void badge(){for(UUID p:List.of(A,B))for(boolean onBench:List.of(false,true))for(boolean printed:List.of(false,true)){
        var m=game(BADGE,printed?Set.of(PokemonFamily.TEAM_PLASMA):Set.of(),GeneratedRuleBatch8Test.hit(100,false));if(p.equals(B))m.endTurn(A);UUID host=onBench?bench(m,p):active(m,p);check(plasma(m,p,host)==printed,"Printed affiliation incorrect");var badge=attach(m,p,host,"trainer");check(plasma(m,p,host),"Badge did not grant affiliation");m.evolveByEffect(p,host,hand(m,p,"evolved").instanceId(),EvolutionPermission.CARD_EFFECT_ALL_TIMING);check(plasma(m,p,host),"Evolution removed attached Badge affiliation");m.devolvePokemonToHandByEffect(p,p,host);check(plasma(m,p,host),"Devolution lost Badge affiliation");m.playTrainer(p,hand(m,p,"stadium").instanceId(),null);check(plasma(m,p,host)==printed,"Lab either retained Badge or erased printed affiliation");m.discardStadiumByEffect(p);check(plasma(m,p,host),"Badge did not restore after Lab");m.discardToolByEffect(p,p,host,badge.instanceId());check(plasma(m,p,host)==printed,"Discarded Badge retained affiliation");
    }var m=game(BADGE);var c=attach(m,A,active(m,A),"trainer");m.disableToolEffectsByEffect(A,A,active(m,A));check(!plasma(m,A,active(m,A)),"Temporary Tool suppression retained Badge");}
    static void machine(){for(UUID p:List.of(A,B))for(boolean onBench:List.of(false,true))for(boolean printed:List.of(false,true))for(boolean take:List.of(false,true)){
        var m=game(MACHINE,printed?Set.of(PokemonFamily.TEAM_PLASMA):Set.of(),GeneratedRuleBatch8Test.hit(100,false));if(p.equals(B))m.endTurn(A);UUID host=onBench?bench(m,p):active(m,p);if(!printed)attach(m,p,host,"badge");var trainer=hand(m,p,"trainer");check(m.canPlayTrainer(p,trainer.instanceId(),null),"Machine rejected current Plasma host");m.playTrainer(p,trainer.instanceId(),null);var q=m.effectCardPrompt(p);check(!q.candidates().isEmpty()&&q.candidates().stream().allMatch(c->c.definitionId().equals(PLASMA)),"Machine selected non-Plasma Energy");var card=q.candidates().getFirst();m.submitEffectCards(p,q.resolutionId(),q.step(),take?List.of(card.instanceId()):List.of());if(take){var target=m.effectAttachmentPrompt(p);check(target.targets().contains(host)&&!target.targets().contains(active(m,other(p)))&&(printed||target.targets().size()==1),"Machine attachment target ignored owner/live Badge");m.chooseEffectAttachmentTarget(p,target.resolutionId(),target.step(),host);}settle(m);check(EventTargetBindingTest.field(m).pokemonView(p,host).attachedEnergyIds().contains(card.instanceId())==take&&!m.energyAttached(p),"Machine used manual quota or failed chosen attachment");
    }for(boolean disabled:List.of(false,true)){var m=game(MACHINE);if(disabled){attach(m,A,active(m,A),"badge");m.playTrainer(A,hand(m,A,"stadium").instanceId(),null);}check(!m.canPlayTrainer(A,hand(m,A,"trainer").instanceId(),null),"Machine accepted absent/suppressed Plasma host");}}
    static void mirror(){for(UUID victim:List.of(A,B))for(boolean onBench:List.of(false,true))for(boolean badge:List.of(false,true))for(PokemonFamily family:List.of(PokemonFamily.TEAM_PLASMA,PokemonFamily.EX_LEGACY,PokemonFamily.EX)){
        var attack=onBench?GeneratedRuleBatch8Test.hit(100,true):DeckDiscardTriggeredAbilityTest.attack(100,"{\"type\":\"damage_counter\",\"target\":\"OPPONENT_ACTIVE\",\"amount\":2}");var m=game(MIRROR,Set.of(family),attack);UUID host=onBench?bench(m,victim):active(m,victim);attach(m,victim,host,"trainer");UUID attacker=other(victim);if(badge)attach(m,attacker,active(m,attacker),"badge");if(attacker.equals(B))m.endTurn(A);m.attack(attacker,"hit");settle(m);boolean blocked=family!=PokemonFamily.EX_LEGACY&&(family==PokemonFamily.TEAM_PLASMA||badge);int damage=EventTargetBindingTest.field(m).pokemonView(victim,host).damage();check(damage==(blocked?0:onBench?100:120),"Mirror wrong affiliation/EX distinction/position/effect protection: "+victim+" bench="+onBench+" badge="+badge+" family="+family+" damage="+damage);
    }for(boolean suppress:List.of(false,true)){var m=game(MIRROR);attach(m,B,active(m,B),"trainer");attach(m,A,active(m,A),"badge");if(suppress)m.disableToolEffectsByEffect(A,A,active(m,A));else{var badge=m.activePokemonView(A).attachedTools().getFirst();m.discardToolByEffect(A,A,active(m,A),badge.instanceId());}m.attack(A,"hit");check(m.lastAttack().finalDamage()==100,"Lost attacker Badge retained Mirror block");}}
    static void trigger(){for(UUID p:List.of(A,B))for(boolean onBench:List.of(false,true))for(String cause:List.of("attack","counter","direct","removed","no-badge")){
        var attack=cause.equals("removed")?BeforeDamageAttackTest.attack("","","{\"type\":\"discard_tool\",\"target\":\"OPPONENT_ACTIVE\",\"amount\":1,\"minimum\":1}"):GeneratedRuleBatch8Test.hit(100,onBench);if(cause.equals("removed")&&onBench)continue;var m=game(TRIGGER,Set.of(),attack);if(p.equals(B))m.endTurn(A);UUID host=onBench?bench(m,p):active(m,p);attach(m,p,host,"trainer");CardInstance badge=cause.equals("no-badge")?null:attach(m,p,host,"badge");NonPokemonBatch75Test.hurt(m,p,host,cause.equals("removed")?980:950);int before=m.privateView(p).hand().size();
        if(cause.equals("direct"))m.knockOutPokemonByEffect(p,p,host);else if(cause.equals("counter"))m.placeDamageCountersByEffect(p,p,host,5);else{m.endTurn(p);m.attack(other(p),"hit");if(cause.equals("removed")){var q=m.effectCardPrompt(other(p));m.submitEffectCards(other(p),q.resolutionId(),q.step(),List.of(badge.instanceId()));}}
        boolean activated=cause.equals("attack");check(m.hasPendingCardSelection()==activated,"Reversal Trigger used wrong KO cause/removed affiliation");if(activated){var q=m.effectCardPrompt(p);check(q.candidates().size()==m.privateView(p).deck().size(),"Reversal search was restricted by category");var chosen=q.candidates().getFirst();m.submitEffectCards(p,q.resolutionId(),q.step(),List.of(chosen.instanceId()));check(m.privateView(p).hand().contains(chosen),"Reversal did not return selected card");}settle(m);check(m.privateView(other(p)).prizes().size()==5,"Reversal changed Prize award");
    }}
    static void ai(){for(String id:IDS)for(var level:AiDifficulty.values()){var m=aiGame(id);m.playTrainer(A,hand(m,A,"trainer").instanceId(),id.equals(MACHINE)?null:active(m,A));var s=MatchSession.multiplayer(m,A,B);AiCardOperationTest.settle(s,level);AiCardOperationTest.finish(s,level);check(m.phase()==MatchPhase.FINISHED,"Plasma field card AI stalled: "+id);}}
    static void schema(){var e=new EffectDefinition("add_pokemon_families",EffectTarget.SELF,Map.of("pokemon_families","TEAM_PLASMA"),List.of(),List.of());for(var source:List.of(PassiveModifierProgram.Source.STADIUM,PassiveModifierProgram.Source.ENERGY,PassiveModifierProgram.Source.ABILITY))GeneratedRuleBatch8Test.reject(()->PassiveModifierProgram.validate(new EffectProgram(List.of(new TriggeredEffects(EffectTrigger.PASSIVE,List.of(),List.of(e)))),source));GeneratedRuleBatch8Test.reject(()->PassiveRuleProgram.validate(new EffectDefinition(e.type(),e.target(),Map.of("pokemon_families","V"),List.of(),List.of())));}
